import openpyxl
# Compare our file's data_only computed values (if any cached) - but openpyxl doesn't recalc.
# Instead verify all non-formula data cells match source exactly.
src=openpyxl.load_workbook('/mnt/hhq/data/data_pipeline/corpus/mimotable_batch1/mimotable_batch1_0321.xlsx', data_only=False)
dst=openpyxl.load_workbook('mimotable_batch1_0321_template_9437_input.xlsx', data_only=False)
ws_s=src['Sheet1']; ws_d=dst['Sheet1']
mismatch=[]
for r in range(2,35):
    for c in range(2,13):
        sv=ws_s.cell(r,c).value; dv=ws_d.cell(r,c).value
        if isinstance(sv,str) and sv.startswith('='):
            if dv!=sv: mismatch.append((r,c,'FORMULA',sv,dv))
        else:
            # numeric/string compare, handle types
            if sv is None and dv is None: continue
            if isinstance(sv,(int,float)) and isinstance(dv,(int,float)):
                if abs(sv-dv)>1e-12: mismatch.append((r,c,'NUM',sv,dv))
            elif sv!=dv:
                mismatch.append((r,c,'VAL',repr(sv),repr(dv)))
print('mismatches', len(mismatch))
for m in mismatch: print(m)
"
